class BoundariesWallModel : public Table {
    public:
        BoundariesWallModel() : Table("") {}
        /** @brief Model constants: 0.41, 17, 0.9 (`equilibrium`), Reynolds analogy factor 1.14 (`gfm`). 3D.
         */
        BoundariesWallModel & A_plus(double v) { put("A_plus", v); return *this; }
        /** @brief Model constants: 0.41, 17, 0.9 (`equilibrium`), Reynolds analogy factor 1.14 (`gfm`). 3D.
         */
        BoundariesWallModel & Pr_t(double v) { put("Pr_t", v); return *this; }
        /** @brief (`gfm`) Height of the boundary-layer edge, where the edge velocity and temperature of the Reynolds
         *        analogy are sampled: a channel's half-height, an estimate of `delta`. Length (m), a number in SI units or
         *        a quantity with its unit; required; 3D.
         */
        BoundariesWallModel & edge_distance(Quantity v) { put("edge_distance", v); return *this; }
        /** @brief `h`, absolute or in heights of the wall cell (twice its centroid's distance to the face); typically `h >=
         *        3` cells and `h <= 0.1-0.3` of the boundary-layer thickness. 3D.
         */
        BoundariesWallModel & exchange_cells(const Value & v) { put("exchange_cells", v); return *this; }
        /** @brief `h`, absolute or in heights of the wall cell (twice its centroid's distance to the face); typically `h >=
         *        3` cells and `h <= 0.1-0.3` of the boundary-layer thickness. Length (m), a number in SI units or a
         *        quantity with its unit; 3D.
         */
        BoundariesWallModel & exchange_distance(Quantity v) { put("exchange_distance", v); return *this; }
        /** @brief Model constants: 0.41, 17, 0.9 (`equilibrium`), Reynolds analogy factor 1.14 (`gfm`). 3D.
         */
        BoundariesWallModel & kappa(double v) { put("kappa", v); return *this; }
        /** @brief `gfm` (default): Griffin, Fu & Moin's (2023) inverse velocity transformation with the generalized
         *        Reynolds analogy, for isothermal and adiabatic walls; `equilibrium`: the equilibrium ODE model
         *        (thin-layer momentum and energy with a damped mixing length), for every wall type. One of equilibrium,
         *        gfm; 3D.
         */
        BoundariesWallModel & model(std::string_view v) { put("model", v); return *this; }
        /** @brief Model constants: 0.41, 17, 0.9 (`equilibrium`), Reynolds analogy factor 1.14 (`gfm`). 3D.
         */
        BoundariesWallModel & s(double v) { put("s", v); return *this; }
};

/** @brief [[initialize.data]]: the keys of this array of tables its parent's setter takes.
 */
class InitializeData : public Table {
    public:
        InitializeData() : Table("") {}
        /** @brief One expression of `x`, `y`, `z` per coordinate, where a point reads the data (default: the file's
         *        metadata, else the coordinates, if named `x`, `y`, `z`). 2D.
         */
        InitializeData & at(const Value & v) { put("at", v); return *this; }
        /** @brief Names of the value columns to read (default: every column but the coordinates). 2D.
         */
        InitializeData & columns(const Value & v) { put("columns", v); return *this; }
        /** @brief Names of the coordinate columns (default: the file's metadata, else the first column for tables, `x`, `y`
         *        (`z`) for points). 2D.
         */
        InitializeData & coordinates(const Value & v) { put("coordinates", v); return *this; }
        /** @brief CSV file: a header of column names, rows of numbers, `#` comments (required). Required.
         */
        InitializeData & file(std::string_view v) { put("file", v); return *this; }
        /** @brief (tables) `linear` (default) or `cubic` (4-point Lagrange per axis). One of cubic, linear; 2D.
         */
        InitializeData & interpolation(std::string_view v) { put("interpolation", v); return *this; }
        /** @brief Prefix of the variables (required). Required.
         */
        InitializeData & name(std::string_view v) { put("name", v); return *this; }
        /** @brief (points) Nearest points weighted by inverse distance squared, 1 to 16 (default 1: the nearest). 2D.
         */
        InitializeData & neighbors(const Value & v) { put("neighbors", v); return *this; }
        /** @brief With `scale`: the scales of the data, e.g. `{length = 0.01, velocity = 30}` (default: the file's
         *        metadata). 2D.
         */
        InitializeData & reference(const InitializeDataReference & t) { put("reference", t); return *this; }
        /** @brief reference as a value (a region's name, an inline table). */
        InitializeData & reference(const Value & v) { put("reference", v); return *this; }
        /** @brief Instead of `at`, one coordinate: the signed distance to this region. 2D.
         */
        InitializeData & region(const Region & t) { put("region", t); return *this; }
        /** @brief region as a value (the name of a region, an inline table). */
        InitializeData & region(const Value & v) { put("region", v); return *this; }
        /** @brief Rescale the data to these scales: `length`, `velocity`, `density`, `temperature`, e.g. `{length = 0.02,
         *        velocity = 15}`; each column by its dimension (velocities by the velocity ratio, Reynolds stresses by its
         *        square, pressures as `rho U^2`), so every column needs a unit (`"1"` if dimensionless). Default none. 2D.
         */
        InitializeData & scale(const InitializeDataScale & t) { put("scale", t); return *this; }
        /** @brief scale as a value (a region's name, an inline table). */
        InitializeData & scale(const Value & v) { put("scale", v); return *this; }
        /** @brief `table` (default): on a grid of 1-3 coordinates, interpolated, end values outside; `points`: scattered,
         *        by nearest points. One of points, table.
         */
        InitializeData & type(std::string_view v) { put("type", v); return *this; }
        /** @brief Units of columns, e.g. `{x = "mm"}` (default: the file's metadata, else SI). 2D.
         */
        InitializeData & units(const Value & v) { put("units", v); return *this; }
};

