/** @brief [numerics.hybrid]: the keys of this table the case sets.
 */
class NumericsHybrid : public Table {
    public:
        NumericsHybrid() : Table("numerics.hybrid") {}
        /** @brief The central flux's states: `cell_averages`, KEEP on the two cells' values, which changes the kinetic
         *        energy by exactly the pressure work on interior faces (second order where the sensor is off; the
         *        reconstructed states still feed the Riemann part); or `reconstructed`, KEEP on the reconstructed face
         *        states, which conserves kinetic energy only to the reconstruction's accuracy and can add it. Default
         *        `cell_averages` with TENO (with TENO's states the central flux adds kinetic energy), `reconstructed` with
         *        MUSCL and first order (the `les` preset's; with no viscosity or SGS model to remove energy, MUSCL's
         *        states add it too, so Euler runs set `cell_averages`). With a gas mixture, `cell_averages` takes each
         *        cell's `gamma` and `e0` (with `double_flux`, the cell's frozen ones). Design. 2D.
         */
        NumericsHybrid & central(std::string_view v) { put("central", v); return *this; }
        /** @brief `kappa` in the sensor's `eps = (kappa c / h)^2`, with each cell's sound speed `c` and size `h = V^(1/d)`,
         *        default 1e-5: a compression without vorticity is a shock only above `|div u| = kappa
         *        sqrt(sensor_threshold / (1 - sensor_threshold)) c / h`, so round-off compressions of uniform flow are
         *        not. Up to about 0.01 every shock is still flagged (`|div u| h / c` of order 0.05 and more) and acoustic
         *        noise (about 3e-3) stops being; but upwinding the noise's compressions is what damps it, and Sod's
         *        problem is 25% less accurate at 0.01. 0 drops `eps`. Design. 2D.
         */
        NumericsHybrid & dilatation_scale(double v) { put("dilatation_scale", v); return *this; }
        /** @brief Ducros sensor above which a cell compressing the flow is a shock, default 0.65 (1 disables the Riemann
         *        solver). 2D.
         */
        NumericsHybrid & sensor_threshold(double v) { put("sensor_threshold", v); return *this; }
        /** @brief Upwind fraction of the other cells, default 0; a small value (e.g. 0.05) damps grid-scale noise on very
         *        irregular meshes, at the cost of numerical dissipation the budget then reports. 2D.
         */
        NumericsHybrid & upwind_floor(double v) { put("upwind_floor", v); return *this; }
};

