/** @brief [chemistry]: the keys of this table the case sets.
 */
class Chemistry : public Table {
    public:
        Chemistry() : Table("chemistry") {}
        /** @brief concentration [kmol/m³] below which reaction orders 0 < n < 1 follow a regularized law (default `1e-12`).
         *        Larger values (e.g. `1e-10`) make trace fuel burning out in hot gas much cheaper to integrate
         *        (`flame_3d`: chemistry 20 to 11.5 ms per step) but change results: after 100 steps of `flame_3d`, T by up
         *        to 0.54 K, Y by up to 3e-5, the integrated heat release by 0.08%. Concentration (m^-3 mol), a number in
         *        kmol/m^3 or a quantity with its unit.
         */
        Chemistry & C_reg(Quantity v) { put("C_reg", v); return *this; }
        /** @brief No chemistry in cells below this temperature (default 0). Temperature (K), a number in SI units or a
         *        quantity with its unit.
         */
        Chemistry & T_frozen(Quantity v) { put("T_frozen", v); return *this; }
        /** @brief Absolute tolerance on the mass fractions (default `1e-10`).
         */
        Chemistry & atol(double v) { put("atol", v); return *this; }
        /** @brief `strang` (default) or `simpler`; `simpler` does not combine with `fuse_half_steps`,
         *        `numerics.double_flux` or `numerics.convective_flux = "hybrid"` (SIMPLER's flow integrator amplifies
         *        non-dissipative operators such as the hybrid flux's central part; see the design notes). One of simpler,
         *        strang.
         */
        Chemistry & coupling(std::string_view v) { put("coupling", v); return *this; }
        /** @brief `false` keeps the mixture non-reacting (default `true`).
         */
        Chemistry & enabled(bool v) { put("enabled", v); return *this; }
        /** @brief `true` first advances each active cell whose last RODAS sub-step covered the whole call by one explicit
         *        Bogacki–Shampine 3(2) step, with no Jacobian and no factorization, and keeps it if its error estimate
         *        passes RODAS's test (`rtol`, `atol`), it leaves no negative mass fraction and it is not stiff (the
         *        stages' estimate of the Jacobian's spectral radius times the step at most 2.5); the other cells take
         *        RODAS as without it, and a cell whose step failed skips it until its RODAS sub-steps have fallen short of
         *        a call (default `false`). It pays where most active cells are not stiff over a call (a 2D H2/air flame:
         *        chemistry 1.8 times faster on an A100, 1.6 on CPUs) and costs little where they are (`flame_3d`: within
         *        0.5%). Results change within the chemistry's tolerances (see the design notes) and stay bitwise
         *        independent of ranks, partition, balancing and step graphs. The examples where it pays set it
         *        (measurements).
         */
        Chemistry & explicit_step(bool v) { put("explicit_step", v); return *this; }
        /** @brief Strang: `true` fuses the closing half step of a step with the next step's opening one, one chemistry call
         *        per step (default `true`). Output, checks, probes and statistics read the state with the pending half
         *        step applied, as the run without fusing has it, on a copy the run does not continue from; restart files
         *        hold the state before it and its time (attribute `CHEMISTRY_PENDING`), so results do not depend on
         *        output, and a restarted run reproduces the uninterrupted one bitwise. A run from such a file without
         *        fusing, or with SIMPLER, applies the pending half step first; one without chemistry ignores it. `false`
         *        takes the two half steps separately, twice the chemistry's cost where cells take few sub-steps; results
         *        agree within the chemistry's tolerances.
         */
        Chemistry & fuse_half_steps(bool v) { put("fuse_half_steps", v); return *this; }
        /** @brief `rosenbrock` (default; RODAS) or `bdf` (variable-order BDF, orders 1-5, with the Jacobian and its
         *        factorization kept over many sub-steps; CVODE's strategy). BDF is faster where cells take one or a few
         *        sub-steps per call, as at the small time steps of detonations and compressible flames (n-dodecane and
         *        n-hexane at `dt` = 1e-8 s: 1.4-1.7 times RODAS's throughput on CPUs, up to 1.4 on an A100), and gains
         *        less at larger time steps, since every call restarts it at order 1 (1.1-1.5 times at 1e-6 s). Its error
         *        estimate is that of the solution it keeps, so at the same `rtol` and `atol` it is less accurate than
         *        RODAS where species below `atol` matter (H2/air ignition delays 2.3% early at `atol = 1e-10`, within 2e-5
         *        at `1e-14`); see the design notes. One of bdf, rosenbrock.
         */
        Chemistry & integrator(std::string_view v) { put("integrator", v); return *this; }
        /** @brief Vector lanes integrating one cell: 1 for one thread per cell (cells ordered by their last cost), a power
         *        of 2 up to 32 for a team per cell on GPUs; default 0, automatic: a warp per cell on GPUs from 16 species
         *        (8 warps, 16 from 512 species, for cells whose last call took 16 or more sub-steps), else one thread.
         */
        Chemistry & lanes(const Value & v) { put("lanes", v); return *this; }
        /** @brief `true` moves the integration of cells from ranks with more chemistry work than the mean (sub-steps of
         *        their cells' last calls) to ranks with less, in every call where the most loaded rank exceeds the mean by
         *        5%; only the cells' states travel, and results stay bitwise the same (default `false`). Each pair of
         *        ranks moves at most its capacity of cells per call, which starts at 0 and follows the cells the pair
         *        asked for (growing at once, shrinking after 256 steps of less than half); the rest stay with their owner,
         *        and a balanced run moves none. With NCCL the messages carry the whole capacity, so that the step's CUDA
         *        graph keeps its sizes; a change of the capacities records it again. The summary reports the time ranks
         *        wait for the slowest rank's chemistry with or without it.
         */
        Chemistry & load_balance(bool v) { put("load_balance", v); return *this; }
        /** @brief Sub-steps allowed per cell and chemistry call (default 100000); more stop the run.
         */
        Chemistry & max_steps(const Value & v) { put("max_steps", v); return *this; }
        /** @brief Relative tolerance on the mass fractions and `T` (default `1e-6`).
         */
        Chemistry & rtol(double v) { put("rtol", v); return *this; }
        /** @brief `true` for the sparse LU (static pattern, with the Jacobian's dense rank-one part by Sherman-Morrison),
         *        `false` for the dense one; by default sparse from 30 species when its factors fill at most 60% of the
         *        dense matrix (GRI-3.0 and larger).
         */
        Chemistry & sparse(const Value & v) { put("sparse", v); return *this; }
};

