/** @brief [run]: the keys of this table the case sets.
 */
class Run : public Table {
    public:
        Run() : Table("run") {}
        /** @brief CFL number in the usual unstructured convention (Blazek eqs. 6.20-6.21; see time step): on a uniform 2D
         *        grid of spacing h, `dt = cfl * h / (abs(u) + abs(v) + 2a)`. Measured stability limits for smooth flow are
         *        1.26-1.6 with SSPRK3 and 1.39-1.8 with RK4, depending on reconstruction and cell type (table): use at
         *        most 1.2 (SSPRK3) or 1.35 (RK4), and 1.0 with SSPRK3 as a robust default, shocks included (but 0.25 for
         *        the Noh problem's infinite-strength shock with `bound_preserving`); with `[chemistry]` the splitting
         *        error may call for less (detonations: about 0.35 with Strang splitting, 1.0 with `coupling = "simpler"`).
         *        Mallard 0.5 and earlier inputs give the same time step with half their `cfl`. Exactly one of `cfl` and
         *        `dt` is required, except that with a numerics preset (also the default `high_order`, which applies when
         *        the input sets neither `[numerics] preset` nor `[numerics.face_reconstruction]`) and neither of them the
         *        preset sets `cfl`.
         */
        Run & cfl(double v) { put("cfl", v); return *this; }
        /** @brief Every this many steps, look for the files `STOP` and `CHECKPOINT` in the working directory (default 0:
         *        never). A file found acts like `mallard ctl stop` or `checkpoint`: at the first step whose time-step
         *        reduction reads the request, within `step_queue` steps of the step the host had reached.
         */
        Run & control_file_interval(std::int64_t v) { put("control_file_interval", v); return *this; }
        /** @brief Serve `mallard ctl` on `mallard.sock` in the working directory (default `true`).
         */
        Run & control_socket(bool v) { put("control_socket", v); return *this; }
        /** @brief CUDA builds (HIP and SYCL builds take their steps kernel by kernel): run each step (time-step reduction,
         *        halo exchanges, stages, the step's end) as one CUDA graph, so the host launches one graph per step
         *        instead of launching each kernel (default `true`). Results are the same bit for bit. Steps run kernel by
         *        kernel with halos exchanged with MPI (`[parallel] halo_exchange = "mpi"`, or builds without NCCL) or
         *        before CUDA 12.4; the run log says so. Turn it off to check kernels with `compute-sanitizer` (details).
         */
        Run & cuda_graphs(bool v) { put("cuda_graphs", v); return *this; }
        /** @brief Fixed time step. Time (s), a number in SI units or a quantity with its unit; required.
         */
        Run & dt(Quantity v) { put("dt", v); return *this; }
        /** @brief Keep a copy of the state at the start of each step (one copy of the conservatives, and partial densities,
         *        per step), so that a diverging run writes the last valid state; see run control (default `true`).
         */
        Run & keep_last_good(bool v) { put("keep_last_good", v); return *this; }
        /** @brief Stop after this many steps.
         */
        Run & n_steps(std::int64_t v) { put("n_steps", v); return *this; }
        /** @brief Steps the host enqueues ahead of the GPU (default 3, at most 64). Each step's time step, end and checks
         *        are decided on the device, so the host does not wait for a step before launching the next; snapshots and
         *        restarts are staged in pinned host memory and written from there; it stops the queue at the steps it acts
         *        on (outputs it writes itself, probes reading `[statistics]` confidence intervals, a moving region's probe
         *        outgrowing its staging, triggers that fire, requests, the end of the run, a divergence) and acts on that
         *        step's state. `1` waits for every step; `0` has the host take every step itself, kernel by kernel.
         *        Results and files are the same bit for bit with any value. More than one step ahead needs the CUDA graphs
         *        of CUDA 12.4 or later; CUDA runs without graphs, and HIP and SYCL builds (whose graphs have no
         *        conditional nodes), take one step at a time (details).
         */
        Run & step_queue(std::int64_t v) { put("step_queue", v); return *this; }
        /** @brief Stop at this simulation time (the last step is shortened to land on it). Time (s), a number in SI units
         *        or a quantity with its unit.
         */
        Run & t_stop(Quantity v) { put("t_stop", v); return *this; }
        /** @brief Stop after this many seconds of wall time. Time (s), a number in SI units or a quantity with its unit.
         */
        Run & t_wall_stop(Quantity v) { put("t_wall_stop", v); return *this; }
};

/** @brief [source]: the keys of this table the case sets.
 */
class Source : public Table {
    public:
        Source() : Table("source") {}
        /** @brief `[g_x, g_y]` (`[g_x, g_y, g_z]` in 3D); adds `rho g` to the momentum and `rho u . g` to the energy
         *        equation. Acceleration (m s^-2), a number in SI units or a quantity with its unit.
         */
        Source & gravity(const std::vector<Quantity> & v) { put("gravity", Value(std::vector<Value>(v.begin(), v.end()))); return *this; }
        /** @brief `[m_x, m_y]` (`[m_x, m_y, m_z]` in 3D): hold the volume average of `rho u` along this vector at its
         *        magnitude with a uniform body force `f` per unit volume along it (constant mass flow, e.g. a periodic
         *        channel). At every Runge-Kutta stage `f` cancels the rate of change of that average from all other terms
         *        (one global sum, exact, so the same on any number of ranks) and closes any remaining gap within the time
         *        step, so a flow started at the target stays there to rounding. The energy gains the force's work `f . u`.
         *        Mass flux (kg m^-2 s^-1), a number in SI units or a quantity with its unit.
         */
        Source & mass_flow(const std::vector<Quantity> & v) { put("mass_flow", Value(std::vector<Value>(v.begin(), v.end()))); return *this; }
        /** @brief Expressions (default none) for the mass, momentum and energy sources, as in `[[sources]]` without a
         *        region (they read the same variables).
         */
        Source & rho(const Value & v) { put("rho", v); return *this; }
        /** @brief Expressions (default none) for the mass, momentum and energy sources, as in `[[sources]]` without a
         *        region (they read the same variables).
         */
        Source & rhoE(const Value & v) { put("rhoE", v); return *this; }
        /** @brief 2D.
         */
        Source & rhoY(const Value & v) { put("rhoY", v); return *this; }
        /** @brief Expressions (default none) for the mass, momentum and energy sources, as in `[[sources]]` without a
         *        region (they read the same variables).
         */
        Source & rhou(const Value & v) { put("rhou", v); return *this; }
        /** @brief Ignored, with a warning: expressions of `t` are re-evaluated at every stage on the device, others once
         *        (Mallard 0.8 and earlier evaluated every expression once unless this was `true`). 2D.
         */
        Source & time_dependent(const Value & v) { put("time_dependent", v); return *this; }
};

